<script>
const firstQuestions = [
  "You regularly make new friends.",
  "Complex and novel ideas excite you more than simple and straightforward ones.",
  "You usually feel more persuaded by what resonates emotionally with you than by factual arguments.",
  "Your living and working spaces are clean and organized.",
  "You usually stay calm, even under a lot of pressure.",
  "You find the idea of networking or promoting yourself to strangers very daunting."
];

const secondQuestions = [
  "You prioritize and plan tasks effectively, often completing them well before the deadline.",
  "People’s stories and emotions speak louder to you than numbers or data.",
  "You like to use organizing tools like schedules and lists.",
  "Even a small mistake can cause you to doubt your overall abilities and knowledge."
];

let page = 0;
const answers = {};
const questionsEl = document.getElementById("questions");

function renderQuestions(){
  const list = page === 0 ? firstQuestions : secondQuestions;
  questionsEl.innerHTML = "";

  if(page > 0){
    const title = document.createElement("h2");
    title.className = "quiz-title";
    title.textContent = "Personality Test";
    questionsEl.appendChild(title);
  }

  list.forEach((text,index)=>{
    const key = page + "-" + index;
    const row = document.createElement("article");
    row.className = "question " + (index===0 ? "active-question" : "");
    row.innerHTML = `
      <h3>${text}</h3>
      <div class="scale">
        <span class="agree">Agree</span>
        <div class="choices">
          ${[0,1,2,3,4,5,6].map(n=>`<button class="choice btn" data-key="${key}" data-value="${n}" aria-label="Answer ${n+1}"></button>`).join("")}
        </div>
        <span class="disagree">Disagree</span>
      </div>`;
    questionsEl.appendChild(row);
  });

  questionsEl.querySelectorAll(".choice").forEach(btn=>{
    const key = btn.dataset.key;
    if(answers[key] === btn.dataset.value) btn.classList.add("selected");
    btn.addEventListener("click",()=>{
      answers[key] = btn.dataset.value;
      document.querySelectorAll(`[data-key="${key}"]`).forEach(x=>x.classList.remove("selected"));
      btn.classList.add("selected");
    });
  });
}

document.getElementById("nextBtn").addEventListener("click",()=>{
  if(page===0){
    page=1;
    document.getElementById("progressFill").style.width="40%";
    document.getElementById("stepText").textContent="Step 2 of 10";
    renderQuestions();
    window.scrollTo({top:document.getElementById("test").offsetTop-85,behavior:"smooth"});
  } else {
    document.getElementById("progressFill").style.width="60%";
    document.getElementById("stepText").textContent="Step 3 of 10";
    document.getElementById("nextBtn").textContent="Continue  →";
    document.querySelector(".next-row").insertAdjacentHTML("beforebegin",
      '<p style="color:#43a97e;font-weight:bold;margin-top:25px">Your answers have been saved.</p>');
  }
});
renderQuestions();
</script>
